/* =============================================================================
 * Authoring vs. Platforms — TEAM REVIEW page only
 * (/authoring-vs-platforms-teamcomment.html — generated by build.js from the
 * live page; this script is not loaded on the public URL)
 *
 * 1. Soft email gate: admits anyone entering an @integral-ed.com address.
 *    Light-touch protection for an internal review link, not real security —
 *    the page content still ships in the response (same approach as the
 *    15th-anniversary preview gate). Email is kept in sessionStorage and
 *    attached to feedback tickets.
 *
 * 2. Per-section feedback pills (NextGenSW pill-comment pattern, as used on
 *    the 15th-anniversary preview): every section gets a small pill in its
 *    bottom-right corner. Clicking opens the WorkBase Tickets form in a NEW
 *    TAB with ?Section=<id>&URL=<full url including #section>&Email=<gate
 *    email>. The form's hidden URL field captures the full referral string,
 *    so each ticket records exactly which section the reviewer clicked from;
 *    tickets land in the WorkBase Tickets table.
 * ============================================================================= */
(function () {
  'use strict';

  var KEY = 'avp-review-email';
  var DOMAIN = /@integral-ed\.com$/i;
  var FEEDBACK_FORM_URL = 'https://workbase.softr.app/feedback-ticket';

  function storedEmail() {
    try { return sessionStorage.getItem(KEY) || ''; } catch (e) { return ''; }
  }

  var unlocked = DOMAIN.test(storedEmail());
  // Applied synchronously (script loads in <head>) so the lock is on
  // before first paint — no content flash.
  if (!unlocked) document.documentElement.classList.add('avp-locked');

  function unlock(mail) {
    unlocked = true;
    try { sessionStorage.setItem(KEY, mail); } catch (e) {}
    document.documentElement.classList.remove('avp-locked');
    var g = document.getElementById('avp-gate');
    if (g) g.setAttribute('hidden', '');
  }

  function buildGate() {
    if (unlocked) return;
    var wrap = document.createElement('div');
    wrap.className = 'avp-gate';
    wrap.id = 'avp-gate';
    wrap.setAttribute('role', 'dialog');
    wrap.setAttribute('aria-modal', 'true');
    wrap.setAttribute('aria-labelledby', 'avp-gate-h');
    wrap.innerHTML =
      '<div class="avp-gate-card">' +
      '  <div class="avp-gate-mark" aria-hidden="true">LMS?</div>' +
      '  <h1 id="avp-gate-h">Team review</h1>' +
      '  <p>This is the internal review copy of the Authoring vs. Platforms page. ' +
      'Enter your Integral Ed email to view it and leave section-by-section comments.</p>' +
      '  <form id="avp-gate-form" autocomplete="email">' +
      '    <input type="email" id="avp-gate-input" placeholder="you@integral-ed.com" ' +
      'aria-label="Your Integral Ed email" autocapitalize="off" spellcheck="false">' +
      '    <button type="submit">Enter &rarr;</button>' +
      '  </form>' +
      '  <p class="avp-gate-err" id="avp-gate-err" role="alert" hidden>' +
      'Use your @integral-ed.com email address.</p>' +
      '</div>';
    document.body.appendChild(wrap);

    var form = document.getElementById('avp-gate-form');
    var input = document.getElementById('avp-gate-input');
    var err = document.getElementById('avp-gate-err');
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var v = (input.value || '').trim();
      if (DOMAIN.test(v)) {
        if (err) err.hidden = true;
        unlock(v.toLowerCase());
      } else {
        if (err) err.hidden = false;
        input.focus();
      }
    });
    input.focus();
  }

  function buildFeedbackUrl(sectionId) {
    var url = location.origin + location.pathname + (sectionId ? '#' + sectionId : '');
    return FEEDBACK_FORM_URL +
      '?Section=' + encodeURIComponent(sectionId) +
      '&URL=' + encodeURIComponent(url) +
      '&Email=' + encodeURIComponent(storedEmail());
  }

  function buildPills() {
    var targets = document.querySelectorAll('.avp-main section[id], .avp-main #myths');
    Array.prototype.forEach.call(targets, function (sec) {
      if (sec.querySelector('.avp-fb-sec')) return;
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'avp-fb-sec';
      btn.dataset.section = sec.id;
      btn.setAttribute('aria-label',
        'Give feedback on the ' + sec.id + ' section (opens a new tab)');
      btn.title = 'Opens a new tab and records this section in the ticket';
      btn.innerHTML = '<span aria-hidden="true">&#128172;</span>' +
        '<span class="avp-fb-sec-label">Feedback</span>';
      sec.appendChild(btn);
    });
    document.addEventListener('click', function (e) {
      var b = e.target.closest ? e.target.closest('.avp-fb-sec') : null;
      if (!b) return;
      window.open(buildFeedbackUrl(b.dataset.section || ''), '_blank', 'noopener');
    });
  }

  function init() {
    buildGate();
    buildPills();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
